def main():
    store = StudyStore(ROOT / "studies")
    study = store.get(STUDY_ID)
    destination = ROOT / "research/russian_politicians_2016_2026"
    original_path = destination / "scales_initial_proposal.json"
    if not original_path.exists():
        original_path.write_text(json.dumps({"scales": study["scales"], "provenance": study.get("scale_provenance")}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    original = {s["id"]: s for s in json.loads(original_path.read_text(encoding="utf-8"))["scales"]}
    scales = []
    for identifier, name, positive, negative, definition, parents, domain in REVISIONS:
        descriptors = []
        objects = set()
        for parent in parents:
            record = original[parent]
            descriptors += [record["name"]] + record.get("aliases", [])
            objects.update(record.get("source_object_ids", []))
        scales.append({"id": identifier, "name": name, "positive": positive, "negative": negative,
                       "definition": definition, "domain": domain, "aliases": list(dict.fromkeys(descriptors)),
                       "source_scale_ids": parents, "source_object_ids": sorted(objects),
                       "descriptor_object_count": len(objects),
                       "frequency_note": "Число объектов в исходном предложении словаря, а не оценка выраженности и не частота в репрезентативном корпусе.",
                       "anchors": {"0": "Полюс не выражен при достаточном объёме относящихся к теме сведений", "1": "Единичное слабое проявление", "3": "Устойчиво заметный публичный акцент", "5": "Определяющий акцент публичного образа"}})
    store.edit(STUDY_ID, "scales", scales)
    provenance = study.get("scale_provenance", {})
    provenance["manual_review"] = {"at": now(), "actor": "research_assistant_before_human_approval",
        "initial_count": len(original), "final_count": len(scales),
        "notes": ["Объединены технократичность и административный прагматизм; цифровизация и технологическая модернизация.",
                  "Региональная и городская темы заменены переносимыми контрастами распределения полномочий и приоритетов повестки.",
                  "Убраны отсутствие темы и молчание как основания противоположного полюса.",
                  "Должность, партийное членство и действительные личные качества не используются как автоматические оценки публичной стратегии.",
                  "Пары являются содержательными контрастами, а не доказанными антонимами. Полюса оцениваются независимо; их совместная выраженность сохраняется.",
                  "Три области — программа, аргументация и стратегия — описывают единый объект: наблюдаемое публичное политическое самопредставление. Общность латентной структуры проверяется, а не предполагается."]}
    store.update(STUDY_ID, scale_provenance=provenance)
    (destination / "scales_for_approval.json").write_text(json.dumps(scales, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    lines = ["# Шкалы пилота: на утверждение", "", "70 политиков России; период 15.10.2016–15.10.2026. Состав объектов утверждён пользователем; эти 26 шкал ещё не утверждены.", "",
             "Измеряем наблюдаемые программные акценты, публичную аргументацию и политическую стратегию. Это признаки публичного образа, а не диагнозы и не оценки личных качеств.", "",
             "Каждый полюс оценивается **отдельно от 0 до 5**. Итоговая координата шкалы = положительный полюс − отрицательный, от −5 до +5. Сохраняем также сумму полюсов: одинаковая разность может скрывать разные сочетания. **Неизвестно = пропуск**, а не ноль. Молчание не служит доказательством противоположной позиции. Ноль допустим только при достаточных относящихся к теме сведениях. Обе позиции могут встречаться в разные годы: это отражается в оценке, уверенности и обосновании.", "",
             "Объединены близкие формулировки, сохранены исходные синонимы и происхождение шкал. Число упоминаний в предложенном словаре не используется как искусственный численный вес. Пары задают содержательные контрасты; их строгая биполярность ещё не установлена эмпирически.", "",
             "| № | Шкала | Полюс + | Полюс − |", "|---:|---|---|---|"]
    for index, scale in enumerate(scales, 1):
        lines.append(f"| {index} | {scale['name']} | {scale['positive']} | {scale['negative']} |")
    lines += ["", "## Операциональные определения", ""]
    for index, scale in enumerate(scales, 1):
        lines += [f"### {index}. {scale['name']}", "", scale["definition"], "", f"Область: {scale['domain']}. Исходные формулировки: {', '.join(scale['aliases'])}.", ""]
    lines += ["## Ограничения", "", "Оценивание LLM — разведочная разметка источников. Один оценщик, неравномерная освещённость, ретроспективное усреднение и взаимозависимость источников ограничивают выводы. Выборка целевая, не репрезентативная; положение политика не доказывает состав его электората. После пилота нужны независимые человеческие оценки, проверка согласия и устойчивости к составу объектов и словарю.", ""]
    (destination / "scales_for_approval.md").write_text("\n".join(lines), encoding="utf-8")
    print(json.dumps({"scales": len(scales), "status": store.get(STUDY_ID)["status"], "objects_approved": store.is_approved(store.get(STUDY_ID), "objects")}, ensure_ascii=False))


if __name__ == "__main__":
    main()
